package androidwhatsapp_test

import (
	"crypto/sha256"
	"encoding/hex"
	"path/filepath"
	"strings"
	"testing"

	"github.com/rbenzing/minutiae/internal/parsers/parsertest"
)

// The fixtures of plan 4I (spec 9.1): generated by tools/fixtures/whatsapp_gen.py, committed, pinned by hash.
const (
	remoteLive           = "/data/data/com.whatsapp/databases/msgstore.db"
	remoteBusiness       = "/data/data/com.whatsapp.w4b/databases/msgstore.db"
	remoteUser10         = "/data/user/10/com.whatsapp/databases/msgstore.db"
	remoteCrypt14        = "/sdcard/WhatsApp/Databases/msgstore.db.crypt14"
	remoteCrypt15        = "/storage/emulated/0/Android/media/com.whatsapp/WhatsApp/Databases/msgstore-2026-11-01.1.db.crypt15"
	remoteBackupBusiness = "/sdcard/WhatsApp Business/Databases/msgstore.db.crypt14"
	remoteBackupPlain    = "/sdcard/WhatsApp/Databases/msgstore.db"
	remoteOther          = "/storage/emulated/0/Android/data/com.whatsapp/databases/msgstore.db"
)

var variants = []string{
	"android-legacy-2.11", "android-transition-legacydata", "android-transition-moderndata", "android-transition-both",
	"android-transition-walonly", "android-transition-empty", "android-modern-2021", "android-modern-2026",
	"android-modern-business", "android-neither", "android-crypt14", "android-crypt15", "android-backup-notsqlite",
	"android-backup-plain", "android-other-location", "android-modern-migrated",
}

// remoteFor is where the variant's database sits on the device.
func remoteFor(variant string) string {
	switch variant {
	case "android-modern-2026":
		return remoteUser10
	case "android-modern-business":
		return remoteBusiness
	case "android-crypt14":
		return remoteCrypt14
	case "android-crypt15":
		return remoteCrypt15
	case "android-backup-notsqlite":
		return remoteBackupBusiness
	case "android-backup-plain":
		return remoteBackupPlain
	case "android-other-location":
		return remoteOther
	}
	return remoteLive
}

func TestFixturesArePinnedByHash(t *testing.T) {
	seen := map[string]bool{}
	for _, v := range variants {
		fx := parsertest.LoadFixture(t, "testdata", v)
		for role, data := range fx.Files {
			sum := sha256.Sum256(data)
			key := v + "." + role
			seen[key] = true
			if want, ok := fixturePins[key]; !ok || want != hex.EncodeToString(sum[:]) {
				t.Errorf("%s: sha256 %x is not the pinned value %q (regenerate image, oracle and pin together)", key, sum, want)
			}
		}
	}
	for key := range fixturePins {
		if !seen[key] {
			t.Errorf("pin %s has no fixture file", key)
		}
	}
}

func TestEveryCommittedFixtureIsInTheVariantList(t *testing.T) {
	all, err := filepath.Glob("testdata/*.expect.json")
	if err != nil {
		t.Fatal(err)
	}
	var m []string
	for _, p := range all {
		if !strings.HasSuffix(p, ".recover.expect.json") { // the typed recovery oracles come with the claims (plan 4I task 14)
			m = append(m, p)
		}
	}
	if len(m) != len(variants) {
		t.Errorf("%d fixtures on disk, %d in the variant list", len(m), len(variants))
	}
	for _, p := range m {
		name := strings.TrimSuffix(filepath.Base(p), ".expect.json")
		known := false
		for _, v := range variants {
			known = known || v == name
		}
		if !known {
			t.Errorf("testdata/%s is not in the variant list", name)
		}
	}
}
